package text

import "testing"

func TestWords(t *testing.T) {
	if len(Words("a b  c")) != 3 {
		t.Fatal("expected three words")
	}
}

func TestWrap(t *testing.T) {
	tests := []struct {
		name   string
		text   string
		width  int
		want   []string
	}{
		{
			name:  "nil on zero width",
			text:  "hello world",
			width: 0,
			want:  nil,
		},
		{
			name:  "nil on negative width",
			text:  "hello world",
			width: -5,
			want:  nil,
		},
		{
			name:  "empty input returns empty slice",
			text:  "",
			width: 10,
			want:  nil,
		},
		{
			name:  "whitespace-only input returns empty slice",
			text:  "   \t\n  ",
			width: 10,
			want:  nil,
		},
		{
			name:  "single word shorter than width",
			text:  "hello",
			width: 10,
			want:   []string{"hello"},
		},
		{
			name:  "single word exactly at width",
			text:  "hello",
			width: 5,
			want:   []string{"hello"},
		},
		{
			name:  "two words fit on one line",
			text:  "hello world",
			width: 20,
			want:   []string{"hello world"},
		},
		{
			name:  "two words need two lines",
			text:  "hello world",
			width: 6,
			want:   []string{"hello", "world"},
		},
		{
			name:  "multiple words with extra whitespace collapses",
			text:  "the  quick   brown fox",
			width: 10,
			want:   []string{"the quick", "brown fox"},
		},
		{
			name:  "word longer than width goes whole",
			text:  "superlongword short",
			width: 5,
			want:   []string{"superlongword", "short"},
		},
		{
			name:  "no trailing or leading spaces",
			text:  "  hello   world  ",
			width: 10,
			want:   []string{"hello", "world"},
		},
		{
			name:  "many words wrap correctly",
			text:  "one two three four five six seven eight nine ten",
			width: 15,
			want:   []string{"one two three", "four five six", "seven eight", "nine ten"},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := Wrap(tt.text, tt.width)
			if len(got) == 0 && got == nil && tt.want == nil {
				return // both nil is fine
			}
			if !equal(got, tt.want) {
				t.Errorf("Wrap(%q, %d) = %v, want %v", tt.text, tt.width, got, tt.want)
			}
		})
	}
}

func equal(a, b []string) bool {
	if a == nil && b == nil {
		return true
	}
	if (a == nil) != (b == nil) {
		return false
	}
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

